        { q: '\u8bd5\u4e86 9 \u79cd\u63a5\u6cd5\uff0c\u5168\u90e8\u6309\u9a8c\u8bc1\u5206\u6392\u5e8f\uff0c\u62a5\u544a\u6700\u597d\u90a3\u79cd\u201c\u63d0\u5347 0.03\u201d\u3002\u8fd8\u9700\u8981\u505a\u4ec0\u4e48\uff1f', o: ['\u4e0d\u9700\u8981\uff0c\u9a8c\u8bc1\u5206\u6700\u9ad8\u5c31\u662f\u6700\u597d', '\u5728\u6d4b\u8bd5\u96c6\u4e0a\u53ea\u770b\u4e00\u6b21\u8fd9\u4e00\u79cd\u7684\u6210\u7ee9\uff0c\u5e76\u62a5\u51fa\u6240\u6709 9 \u79cd\u7684\u7ed3\u679c', '\u5728\u6d4b\u8bd5\u96c6\u4e0a\u628a 9 \u79cd\u90fd\u6bd4\u4e00\u904d\u518d\u6311', '\u6362\u4e00\u4e2a\u6307\u6807\u91cd\u65b0\u6311'], a: 1, e: '\u6311\u9009\u53ea\u80fd\u5728\u9a8c\u8bc1\u96c6\u4e0a\u505a\uff1b\u6311\u5b8c\u540e\u6d4b\u8bd5\u96c6\u53ea\u770b\u4e00\u6b21\uff0c\u5e76\u4e14\u6240\u6709\u65b9\u6848\u90fd\u8981\u62a5\u3002' },
        { q: '\u201c\u52a0\u96f7\u8fbe\u901a\u9053\u6ca1\u6709\u7a33\u5b9a\u589e\u76ca\u201d\u8fd9\u4e2a\u7ed3\u679c\u5e94\u8be5\uff1a', o: ['\u4e0d\u5199\u8fdb\u62a5\u544a\uff0c\u56e0\u4e3a\u662f\u8d1f\u7ed3\u679c', '\u5199\u8fdb\u62a5\u544a\uff1a\u5b83\u672c\u8eab\u5c31\u662f\u6709\u4ef7\u503c\u7684\u7ed3\u8bba', '\u6362\u4e2a\u79cd\u5b50\u76f4\u5230\u6709\u589e\u76ca', '\u53ea\u62a5\u597d\u7684\u90a3\u4e2a\u79cd\u5b50'], a: 1, e: '\u8d1f\u7ed3\u679c\u4e5f\u662f\u7ed3\u679c\uff0c\u5220\u6389\u5b83\u4f1a\u8ba9\u8bfb\u8005\u9ad8\u4f30\u65b9\u6cd5\u7684\u6548\u679c\u3002' },
        { q: '\u9879\u76ee Q3 \u4e3a\u4ec0\u4e48\u8981\u5728 U-Net\u3001Changer\u3001ChangeMamba\u3001OlmoEarth \u8fd9\u51e0\u4e2a\u4ee3\u8868\u4e0a\u505a\uff0c\u800c\u4e0d\u662f\u53ea\u7528 U-Net \u548c FC-Siam-diff\uff1f', o: ['\u56e0\u4e3a\u5b83\u4eec\u8bad\u7ec3\u6700\u5feb', '\u53ea\u7528\u4e24\u4e2a\u6700\u7b80\u5355\u7684 CNN\uff0c\u7ed3\u8bba\u63a8\u4e0d\u5230 Transformer\u3001Mamba\u3001\u5927\u6a21\u578b\u4e0a', '\u56e0\u4e3a\u5b83\u4eec\u7684 F1 \u6700\u9ad8', '\u4e3a\u4e86\u7528\u5b8c\u670d\u52a1\u5668'], a: 1, e: '\u4ee3\u8868\u8981\u8986\u76d6\u6bcf\u7c7b\u7ed3\u6784\uff0c\u5e76\u6309\u9a8c\u8bc1\u5206\u9009\u51fa\uff0c\u7ed3\u8bba\u624d\u6709\u4e00\u822c\u6027\u3002' }
